CREATE TABLE schema_meta (singleton INTEGER PRIMARY KEY CHECK(singleton=1), schema_version INTEGER NOT NULL, instance_uuid TEXT NOT NULL, fixed_digest TEXT NOT NULL, restore_id TEXT, recovery_pending INTEGER NOT NULL DEFAULT 0, admission_floor_ms INTEGER NOT NULL DEFAULT 0);
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL,name TEXT NOT NULL,cwd TEXT NOT NULL,dev INTEGER NOT NULL,ino INTEGER NOT NULL,lifecycle TEXT NOT NULL CHECK(lifecycle IN ('ACTIVE','RETIRED')),default_model TEXT NOT NULL);
CREATE UNIQUE INDEX active_channel ON projects(channel_id) WHERE lifecycle='ACTIVE';
CREATE TABLE conversations(thread_id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id),paused INTEGER NOT NULL DEFAULT 0,pause_revision INTEGER NOT NULL DEFAULT 0,next_sequence INTEGER NOT NULL DEFAULT 0,next_control_sequence INTEGER NOT NULL DEFAULT 0,latest_model_sequence INTEGER NOT NULL DEFAULT 0,selected_model TEXT NOT NULL,effective_model TEXT,effective_sequence INTEGER NOT NULL DEFAULT 0,selection_revision INTEGER NOT NULL DEFAULT 0,proxy_thread_id TEXT UNIQUE,last_response_id TEXT,last_success_sequence INTEGER NOT NULL DEFAULT 0,continuation TEXT NOT NULL DEFAULT 'NEW');
CREATE TABLE admissions(message_id TEXT PRIMARY KEY,request_id TEXT NOT NULL UNIQUE,thread_id TEXT NOT NULL REFERENCES conversations(thread_id),sequence INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('VALIDATING','ACCEPTED','REJECTED','QUARANTINED')),version INTEGER NOT NULL DEFAULT 0,metadata_digest TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,error_code TEXT,UNIQUE(thread_id,sequence));
CREATE TABLE requests(id TEXT PRIMARY KEY,message_id TEXT NOT NULL UNIQUE REFERENCES admissions(message_id),thread_id TEXT NOT NULL REFERENCES conversations(thread_id),sequence INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('RECEIVED','QUEUED','SENDING','RUNNING','APPROVAL_REQUIRED','CANCEL_REQUESTED','COMPLETED','FAILED','CANCELLED','UNKNOWN')),version INTEGER NOT NULL DEFAULT 0,input_digest TEXT NOT NULL,client_request_id TEXT UNIQUE,dispatch_started_at INTEGER,dispatch_eligible INTEGER NOT NULL DEFAULT 1,restore_id TEXT,response_id TEXT UNIQUE,proxy_thread_id TEXT,turn_id TEXT UNIQUE,model TEXT,model_revision INTEGER,previous_response_id TEXT,stop_requested INTEGER NOT NULL DEFAULT 0,error_code TEXT,updated_at INTEGER NOT NULL);
CREATE TRIGGER no_dispatch_rewind BEFORE UPDATE ON requests WHEN (OLD.dispatch_started_at IS NOT NULL AND (NEW.dispatch_started_at IS NULL OR NEW.state IN ('RECEIVED','QUEUED'))) OR (OLD.dispatch_eligible=0 AND NEW.dispatch_eligible=1) BEGIN SELECT RAISE(ABORT,'dispatch boundary immutable'); END;
CREATE TABLE request_attachments(request_id TEXT NOT NULL REFERENCES requests(id),attachment_id TEXT NOT NULL,ordinal INTEGER NOT NULL,bytes INTEGER NOT NULL,digest TEXT NOT NULL,kind TEXT NOT NULL,PRIMARY KEY(request_id,attachment_id));
CREATE TABLE holds(request_id TEXT PRIMARY KEY REFERENCES requests(id),project_id TEXT NOT NULL REFERENCES projects(id),released INTEGER NOT NULL DEFAULT 0,generation INTEGER NOT NULL DEFAULT 0);
CREATE TABLE request_events(id INTEGER PRIMARY KEY,request_id TEXT NOT NULL REFERENCES requests(id),old_state TEXT,new_state TEXT NOT NULL,reason TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE operations(id TEXT PRIMARY KEY,interaction_id TEXT UNIQUE,thread_id TEXT REFERENCES conversations(thread_id),sequence INTEGER,kind TEXT NOT NULL,target_request_id TEXT,target_turn_id TEXT,target_thread_id TEXT,approval_id TEXT,decision TEXT,expected_revision INTEGER,input_digest TEXT,desired_model TEXT,state TEXT NOT NULL DEFAULT 'VALIDATING',send_state TEXT NOT NULL DEFAULT 'NOT_SENT',created_at INTEGER NOT NULL,error_code TEXT);
CREATE TABLE deliveries(id TEXT PRIMARY KEY,target_id TEXT NOT NULL,thread_id TEXT NOT NULL,kind TEXT NOT NULL,part INTEGER NOT NULL,message_id TEXT UNIQUE,state TEXT NOT NULL,confirmed_revision INTEGER NOT NULL DEFAULT 0,confirmed_digest TEXT,pending_revision INTEGER,pending_digest TEXT,created_at INTEGER NOT NULL,UNIQUE(target_id,kind,part));
CREATE TABLE approvals(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES requests(id),thread_id TEXT NOT NULL,turn_id TEXT NOT NULL,state TEXT NOT NULL,expires_at INTEGER,message_id TEXT,operation_id TEXT UNIQUE);
CREATE TABLE admin_audit(id TEXT PRIMARY KEY,uid INTEGER NOT NULL,kind TEXT NOT NULL,target_id TEXT NOT NULL,reason TEXT NOT NULL,risk_accepted INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE restore_blocks(restore_id TEXT NOT NULL,project_id TEXT NOT NULL REFERENCES projects(id),released INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(restore_id,project_id));
CREATE TABLE conversation_creations(interaction_id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),state TEXT NOT NULL,thread_id TEXT UNIQUE);
CREATE INDEX admission_queue ON admissions(thread_id,sequence,status);
CREATE INDEX request_queue ON requests(state,thread_id,sequence);
CREATE TABLE output_state(request_id TEXT PRIMARY KEY REFERENCES requests(id),state TEXT NOT NULL CHECK(state IN ('VOLATILE','UNAVAILABLE','DELIVERED')));
CREATE TABLE notices(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL,code TEXT NOT NULL,created_at INTEGER NOT NULL);
ALTER TABLE schema_meta ADD COLUMN config_revision INTEGER NOT NULL DEFAULT 1;
ALTER TABLE requests ADD COLUMN capability_epoch INTEGER;
ALTER TABLE requests ADD COLUMN capability_digest TEXT;
ALTER TABLE requests ADD COLUMN config_revision INTEGER;
ALTER TABLE admissions ADD COLUMN limits_json TEXT NOT NULL DEFAULT '{}';
